import { test, expect } from '@playwright/test';

test.describe('Login Error States - Locked Out User', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('should display locked out error message when using locked user credentials', async ({ page }) => {
    // Locate and fill username field using getByLabel
    const usernameField = page.getByLabel('Username');
    await usernameField.fill('locked_out_user');

    // Locate and fill password field using getByLabel
    const passwordField = page.getByLabel('Password');
    await passwordField.fill('secret_sauce');

    // Locate and click login button using getByRole
    const loginButton = page.getByRole('button', { name: 'Login' });
    await loginButton.click();

    // Wait for error message to appear
    await page.waitForSelector('[data-test="error"]');

    // Verify error container is visible
    const errorContainer = page.locator('[data-test="error"]');
    await expect(errorContainer).toBeVisible();

    // Verify error message contains specific text
    const errorMessage = page.getByText(/Sorry, this user has been locked out/);
    await expect(errorMessage).toBeVisible();

    // Verify user is still on the login page
    const loginPageUrl = page.url();
    expect(loginPageUrl).toContain('saucedemo.com/login');
  });

  test('should not navigate to inventory page when locked out user attempts login', async ({ page }) => {
    // Locate and fill username field using getByLabel
    const usernameField = page.getByLabel('Username');
    await usernameField.fill('locked_out_user');

    // Locate and fill password field using getByLabel
    const passwordField = page.getByLabel('Password');
    await passwordField.fill('secret_sauce');

    // Locate and click login button using getByRole
    const loginButton = page.getByRole('button', { name: 'Login' });
    await loginButton.click();

    // Wait for error message to appear
    await page.waitForSelector('[data-test="error"]');

    // Verify error message is displayed
    const errorContainer = page.locator('[data-test="error"]');
    await expect(errorContainer).toBeVisible();

    // Verify inventory page URL is not present
    const inventoryUrl = page.url();
    expect(inventoryUrl).not.toContain('inventory.html');

    // Verify login button is still visible and enabled
    const loginButtonAfterError = page.getByRole('button', { name: 'Login' });
    await expect(loginButtonAfterError).toBeVisible();
    await expect(loginButtonAfterError).not.toBeDisabled();
  });
});
